# Find the next event without using lambda
if len(future_events) == 0:
    raise ValueError("No upcoming Yoga classes found.")

next_event = future_events[0]
for event in future_events:
    if event.start_time < next_event.start_time:
        next_event = event

print(next_event.start_time.strftime("%Y-%m-%d %H:%M"))
